<?php
declare(strict_types=1);
$root=getenv('RUNNER_TEMP').'/local';require $root.'/bootstrap.php';$core=sokna_local_bootstrap(require dirname($root).'/config.php');$p=$core->database();
$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$a=function($ok,$m){if(!$ok)throw new RuntimeException($m);};
$one=function($sql,$args=[])use($p){$s=$p->prepare($sql);$s->execute($args);return $s->fetchColumn();};
$rows=function($sql,$args=[])use($p){$s=$p->prepare($sql);$s->execute($args);return $s->fetchAll(PDO::FETCH_ASSOC);};
$run=function($sql,$args=[])use($p){$s=$p->prepare($sql);$s->execute($args);return (int)$p->lastInsertId();};
$admin=$run("INSERT INTO users(username,password_hash,display_name,role,active) VALUES(?,?,?,'admin',1)",['ci_fin_admin',password_hash('test-only-disposable',PASSWORD_DEFAULT),'QA admin']);
$operator=$run("INSERT INTO users(username,password_hash,display_name,role,active) VALUES(?,?,?,'operator',1)",['ci_fin_operator',password_hash('test-only-disposable',PASSWORD_DEFAULT),'QA operator']);
$user=['id'=>$admin];$day=(new DateTimeImmutable('now',new DateTimeZone('Asia/Tehran')))->modify('-1 day')->format('Y-m-d');
$table=$run("INSERT INTO cafe_tables(name,table_number,code,access_token) VALUES(?,?,?,?)",['QA table',65000,'ci-finance-table','ci-finance-token']);
$session=$run("INSERT INTO table_sessions(public_token,table_id,status,live_table_guard,opened_by_user_id,business_date,business_shift_key,business_shift_label,business_cutoff_snapshot) VALUES(?,?,'active',?,?,?,?,?,?)",['ci-finance-session',$table,$table,$admin,$day,'day','روز','00:00']);
$catalog=$core->orderCatalog()->staffCatalogRows();$item=null;
foreach($catalog as $v)if(!$v['is_bundle']&&$v['price']>10000&&$one("SELECT COUNT(*) FROM inventory_recipe_versions WHERE menu_item_id=? AND status='active'",[$v['id']])>0){$item=$v;break;}
$a(is_array($item),'no approved catalog recipe');
$code=(string)$one('SELECT item_code FROM items WHERE id=?',[$item['id']]);
$ingredients=$rows("SELECT c.inventory_item_id,c.quantity_base,i.base_unit FROM inventory_recipe_components c JOIN inventory_recipe_versions v ON v.id=c.recipe_version_id JOIN inventory_items i ON i.id=c.inventory_item_id WHERE v.menu_item_id=? AND v.status='active' AND c.quantity_base>0",[$item['id']]);
$a(count($ingredients)>0,'no recipe ingredients');
$opening=$core->inventoryCounts()->start(['session_type'=>'opening','title'=>'QA count'],$user);
foreach($ingredients as $i){$l=$rows("SELECT id,updated_at FROM inventory_count_lines WHERE session_id=? AND inventory_item_id=?",[$opening['session_id'],$i['inventory_item_id']])[0];$core->inventoryCounts()->updateLine(['session_id'=>$opening['session_id'],'line_id'=>$l['id'],'expected_version'=>$l['updated_at'],'actual_major'=>'100','opening_total_cost'=>'1000000'],$user);}
$core->inventoryCounts()->finalize($opening['session_id'],$user);
$balance=function($id)use($one){return (int)$one("SELECT quantity_base FROM inventory_balances WHERE inventory_item_id=?",[$id]);};
$initial=[];foreach($ingredients as $i)$initial[$i['inventory_item_id']]=$balance($i['inventory_item_id']);
$order=function($token,$q)use($core,$item,$table,$session,$admin){return $core->orders()->commit(['source'=>'staff','table_id'=>$table,'session_id'=>$session,'client_token'=>$token,'actor_user_id'=>$admin,'items'=>[['id'=>$item['id'],'quantity'=>$q]]]);};
$cancel=$order('ci-b-cancel-order',1);
$core->inventoryOrders()->processPending();
foreach($ingredients as $i)$a($balance($i['inventory_item_id'])===$initial[$i['inventory_item_id']]-(int)$i['quantity_base'],'actual consumption missing');
$cancelReq=['order_id'=>$cancel['order_id'],'request_id'=>'ci-b-cancel-request','reason'=>'لغو آزمایشی'];
$core->orderStaffActions()->cancelWholeOrder($cancelReq,$user);
$core->inventoryOrders()->processPending();
foreach($ingredients as $i)$a($balance($i['inventory_item_id'])===$initial[$i['inventory_item_id']],'stock restoration mismatch');
$a(($core->orderStaffActions()->cancelWholeOrder($cancelReq,$user)['idempotent']??false)===true,'cancel replay');
echo "PASS actual MariaDB recipe consumption and cancellation restoration ".$code."\n";
$o=$order('ci-b-finance-order',2);$core->inventoryOrders()->processPending();
$a(($order('ci-b-finance-order',2)['duplicate']??false)===true,'order replay');
$svc=$core->settlements();
$svc->setDiscount($session,'fixed',1000,$user);
$acc=$svc->account($session);$a($acc['subtotal']===(int)$item['price']*2 && $acc['discount']===1000,'discount calculation');
$line=$o['lines'][0]['order_item_id'];
$req=function($ac,$mode,$id,$sel=[])use($session){return ['session_id'=>$session,'expected_session_id'=>$session,'expected_remaining_total'=>$ac['remaining_total'],'expected_signature'=>$ac['signature'],'mode'=>$mode,'destination'=>'direct','request_id'=>$id,'selection'=>$sel,'print_receipt'=>false];};
$first=$req($acc,'itemized','ci-b-itemized-001',[['order_item_id'=>$line,'quantity'=>1]]);
try{$svc->review($first,['id'=>$operator]);throw new LogicException('unauthorized operator succeeded');}catch(\Sokna\Local\Domain\Settlement\SettlementException $e){}
$rv=$svc->review($first,$user);$part=(int)$rv['total'];$a($part>1,'invalid first total');
$first['tenders']=['cash'=>intdiv($part,2),'pos'=>$part-intdiv($part,2)];
$paid=$svc->settle($first,$user);$a($paid['total_amount']===$part&&!$paid['closes_session'],'partial settlement');
$a($svc->settle($first,$user)['idempotent']===true,'payment replay');
$paidBefore=$rows('SELECT * FROM settlement_records WHERE id=?',[$paid['settlement_id']]);
$acc=$svc->account($session);
$grant=$svc->setDiscount($session,'fixed',2000,$user,$acc['signature']);
$a($grant['remaining_only']===true&&$grant['discount_amount']===2000,'remaining grant');
$acc=$svc->account($session);
$rev=$svc->adjustRemainingDiscount($session,'fixed',3000,$acc['signature'],'اصلاح آزمایشی','ci-b-discount-rev',$user);
$a($rev['discount_amount']===3000,'discount revision');
$a($rows('SELECT * FROM settlement_records WHERE id=?',[$paid['settlement_id']])===$paidBefore,'paid receipt changed');
$acc=$svc->account($session);$second=$req($acc,'full','ci-b-final-001');
$rv2=$svc->review($second,$user);$second['tenders']=['pos'=>$rv2['total']];
$final=$svc->settle($second,$user);
$a($final['closes_session']&&$final['remaining_total']===0,'closure');
$sum=(int)$one("SELECT SUM(total) FROM settlement_records WHERE session_id=? AND status='completed'",[$session]);
$a($sum===$paid['total_amount']+$final['total_amount'],'ledger sum');
$a((int)$one("SELECT SUM(t.amount) FROM settlement_tender_allocations t JOIN settlement_records r ON r.id=t.settlement_id WHERE r.session_id=?",[$session])===$sum,'tenders sum');
$cashDay=(string)$one('SELECT business_date FROM settlement_records WHERE id=?',[$paid['settlement_id']]);
$a($cashDay!==$day,'fixture dates not distinct');
$sales=$core->reporting()->report($day,$day)['summary'];$cash=$core->reporting()->report($cashDay,$cashDay)['summary'];
$a($sales['net_sales']===$sum&&$sales['invoice_count']===1&&$sales['avg_ticket']===$sum,'sales opening day mismatch');
$a($cash['completed_amount']===$sum&&$cash['net_sales']===0,'cash day mismatch');
echo json_encode(['status'=>'PASS','order'=>$code,'inventory_restored'=>true,'unauthorized_operator_denied'=>true,'idempotent'=>true,'discount_revision'=>true,'two_payments_one_invoice'=>true,'sales_cash_days_separate'=>true,'total'=>$sum],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)."\n";
